export const GROUND_BYTES={"chao-grama-viva": "", "chao-musgo": "", "chao-grama-baixa": "", "chao-grama-seca": "", "chao-bosque-sombrio": "", "chao-prado-florido": "", "chao-brejo": "", "chao-serra": "", "chao-folhagem": "", "chao-terra-rubra": "", "chao-terra-escura": "", "chao-trilha": "", "chao-areia-dourada": "", "chao-areia-clara": "", "chao-areia-umida": "", "chao-cascalho": "", "chao-lodo": "", "chao-raizes": "", "chao-calcamento": "", "chao-pedra-musgosa": "", "chao-ruinas": "", "chao-tijolos": "", "chao-ardosia": "", "chao-basalto": "", "chao-cinzas": "", "chao-neve": "", "chao-gelo": ""};
export const GROUND_COLORS={"chao-grama-viva": {"color": "#588f4b", "dark": "#3e6434", "light": "#6bae5c"}, "chao-musgo": {"color": "#72913e", "dark": "#50662b", "light": "#8bb14c"}, "chao-grama-baixa": {"color": "#6a7e43", "dark": "#4a582f", "light": "#819a52"}, "chao-grama-seca": {"color": "#c49b4f", "dark": "#896c37", "light": "#efbd60"}, "chao-bosque-sombrio": {"color": "#265850", "dark": "#1b3e38", "light": "#2e6b62"}, "chao-prado-florido": {"color": "#648e4c", "dark": "#466335", "light": "#7aad5d"}, "chao-brejo": {"color": "#467d68", "dark": "#315849", "light": "#55987f"}, "chao-serra": {"color": "#658864", "dark": "#475f46", "light": "#7ba67a"}, "chao-folhagem": {"color": "#46764d", "dark": "#315336", "light": "#55905e"}, "chao-terra-rubra": {"color": "#aa4e37", "dark": "#773726", "light": "#cf5f43"}, "chao-terra-escura": {"color": "#5c362f", "dark": "#402621", "light": "#704239"}, "chao-trilha": {"color": "#aa6744", "dark": "#774830", "light": "#cf7e53"}, "chao-areia-dourada": {"color": "#eeb45f", "dark": "#a77e42", "light": "#ffdc74"}, "chao-areia-clara": {"color": "#f5d29d", "dark": "#ac936e", "light": "#ffffc0"}, "chao-areia-umida": {"color": "#b49676", "dark": "#7e6953", "light": "#dcb790"}, "chao-cascalho": {"color": "#b47e56", "dark": "#7e583c", "light": "#dc9a69"}, "chao-lodo": {"color": "#755a3a", "dark": "#523f29", "light": "#8f6e47"}, "chao-raizes": {"color": "#5f372e", "dark": "#422620", "light": "#744338"}, "chao-calcamento": {"color": "#8a8389", "dark": "#615c60", "light": "#a8a0a7"}, "chao-pedra-musgosa": {"color": "#838673", "dark": "#5c5e50", "light": "#a0a38c"}, "chao-ruinas": {"color": "#b9ae95", "dark": "#827a68", "light": "#e2d4b6"}, "chao-tijolos": {"color": "#a36b5e", "dark": "#724b42", "light": "#c78373"}, "chao-ardosia": {"color": "#4d6476", "dark": "#364653", "light": "#5e7a90"}, "chao-basalto": {"color": "#54515e", "dark": "#3b3942", "light": "#666373"}, "chao-cinzas": {"color": "#766971", "dark": "#534a4f", "light": "#90808a"}, "chao-neve": {"color": "#cde0fb", "dark": "#909db0", "light": "#faffff"}, "chao-gelo": {"color": "#9dcbda", "dark": "#6e8e99", "light": "#c0f8ff"}};

const boardPixels=new Uint8Array(3*32*32*4);
for(let variant=0;variant<3;variant++)for(let y=0;y<32;y++)for(let x=0;x<32;x++){
  const u=x%31,v=y%31,edge=u===0||v===0;
  const seam=v%8===0;
  const grain=(u*7+Math.floor(v/2)*11+(edge?0:variant*13))%23;
  const shade=seam?-31:v%8===1?12:grain===3?-12:grain===7?8:0;
  const offset=(variant*1024+y*32+x)*4;
  boardPixels.set([166+shade,112+shade,65+shade,255],offset);
}
GROUND_BYTES['chao-tabua']=btoa(String.fromCharCode(...boardPixels));
GROUND_COLORS['chao-tabua']={dark:'#674225',light:'#c89158'};
